/**
 * Tex's one config is what the gateway runs (Dev2, 2026-11-13: "I want the config generated by the lab to become the
 * production code, and to be the only source of truth"). Each model-calling step asks `texConfig.js` for its model,
 * effort and time limit, and the texting setup's models come from the config, never from the setup note.
 *
 * Sabotage record (temporary local edits, reverted, 2026-11-13):
 *   replyJudge.js back to its own `effort: "low"`             "each judge asks the config how hard to think" fails
 *   texSetupFront() giving main effort high                   "a setup note with no models runs on the config's" fails
 *   the router on in texConfig.json                           "a step the code cannot run is never on" fails
 * (2026-11-14)
 *   texModules() giving a job the front door's modules         "each step's prompt modules are the p- entries" fails
 *   wordsDiffer always []                                      "a note that names its own modules keeps them" fails
 *   one word changed in texPrompt/rules.md, not regenerated    "the generated words are the Markdown files'" fails
 */
import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";

import { texPick, TEX_CONFIG, TEX_PROMPT_WORDS, texEffort, texModel, texModules, texSetupFront, texStep, texTimeoutMs } from "../src/agent/texConfig.js";
import { frontOf, parseSetup } from "../src/agent/production.js";
import { assembleSetup, modulePath } from "../src/agent/promptModules.js";
import { moduleIsCurrent as promptModuleIsCurrent } from "../../../scripts/tex-prompt-module.mjs";
import { trainName } from "../../../packages/shared/src/texTraining.cjs";
import { REVIEW_MODEL, REVIEW_TIMEOUT_MS } from "../src/agent/replyJudge.js";
import { MAIL_CHECKER_MODEL } from "../src/agent/mailChecker.js";
import { CARD_CHECK_MODEL } from "../src/agent/cardCheck.js";
import { HANDBACK_JUDGE_MODEL } from "../src/agent/handbackJudge.js";
import { SELF_REVIEW_MODEL } from "../src/agent/selfReview.js";
import { THREADS_MODEL, THREADS_TIMEOUT_MS } from "../src/agent/conversationThreads.js";
import { ADVISOR_TIMEOUT_MS } from "../src/agent/advisor.js";

const FINGERPRINT_SETUP = new URL("../bench/fingerprint/setups/texting-assistant/production.md", import.meta.url);
const src = (file) => readFileSync(new URL(`../src/agent/${file}`, import.meta.url), "utf8");

test("every step's model is in the config's table, and every wire joins two steps", () => {
  const ids = new Set(TEX_CONFIG.nodes.map((n) => n.id));
  for (const n of TEX_CONFIG.nodes) if (n.model !== "code") assert.equal(typeof TEX_CONFIG.models[n.model], "string", n.id);
  for (const e of TEX_CONFIG.edges) assert.ok(ids.has(e.from) && ids.has(e.to), `${e.from} -> ${e.to}`);
  assert.equal(ids.size, TEX_CONFIG.nodes.length, "step ids are unique");
});

test("each judge's model and time limit is the config's", () => {
  assert.deepEqual(
    [REVIEW_MODEL, MAIL_CHECKER_MODEL, CARD_CHECK_MODEL, HANDBACK_JUDGE_MODEL, SELF_REVIEW_MODEL, THREADS_MODEL],
    ["reviewer", "mail", "card", "handback", "selfreview", "classifier"].map((id) => texModel(id)),
  );
  assert.deepEqual([REVIEW_TIMEOUT_MS, THREADS_TIMEOUT_MS, ADVISOR_TIMEOUT_MS.chat], [texTimeoutMs("reviewer"), texTimeoutMs("classifier"), texTimeoutMs("advisor")]);
});

test("each judge asks the config how hard to think, and no model file keeps an effort or model id of its own", () => {
  // A step a draft may fold into another reads the folded one first (`texPick`): "answerCheck" before "reviewer".
  for (const [file, id] of [["replyJudge.js", 'texPick\\(\\["answerCheck", "reviewer"\\], config\\?\\.tex\\)'], ["mailChecker.js", '"mail"'], ["cardCheck.js", '"card"'], ["handbackJudge.js", '"handback"'], ["selfReview.js", 'texPick\\(\\["afterReply", "selfreview"\\], config\\?\\.tex\\)'], ["conversationThreads.js", 'texPick\\(\\["afterReply", "classifier"\\], config\\?\\.tex\\)']]) {
    const text = src(file);
    assert.match(text, new RegExp(`texEffort\\(${id}, config\\?\\.tex\\)`), file); // main's, or a Lab test chat's draft (`aiGatewayConfig`)
    assert.match(text, new RegExp(`texModel\\(${id}, config\\?\\.tex\\)`), file);
    assert.doesNotMatch(text, /effort: "(?:off|low|medium|high|xhigh|max)"/, file);
    assert.doesNotMatch(text, /= "anthropic\/claude-[a-z0-9.-]+"/, file);
  }
  assert.deepEqual(texEffort("classifier"), { effort: "low", thinking: "off" });
  assert.deepEqual(texEffort("reviewer"), { effort: texStep("reviewer").effort });
  // Main's config has the folded steps since the simpler graph was promoted (Dev2, 2026-11-16), so each reads the folded one.
  assert.deepEqual([texPick(["answerCheck", "reviewer"]), texPick(["afterReply", "classifier"]), texPick(["afterReply", "selfreview"])], ["answerCheck", "afterReply", "afterReply"]);
  assert.deepEqual(texEffort("afterReply"), { effort: "low", thinking: "off" }, "After the reply thinks no more than the Classifier did");
  assert.throws(() => texPick(["nope", "neither"]), /no step "nope" or "neither"/);
});

test("a setup note with no models runs on the config's, exactly as the same note naming the config's models", async () => {
  const bare = readFileSync(FINGERPRINT_SETUP, "utf8").replace(/^modules:\n(?: {2}.*\n)+/m, "");
  assert.doesNotMatch(bare, /^(?:models|reply_judge|plan_big_asks):/m, "the fingerprint copy names no models, as production's note names none");
  const front = texSetupFront();
  const lines = Object.entries(front.models).map(([k, v]) => `  ${k}: ${JSON.stringify(v)}`).join("\n");
  const named = await parseSetup(bare.replace(/^---\n/, `---\nmodels:\n${lines}\nreply_judge: ${front.reply_judge}\n`));
  const fromConfig = await parseSetup(bare);
  assert.ok(named && fromConfig, "both parse");
  // Only the models are under test here: a note naming no modules also gets the config's words (the test below).
  const strip = ({ version, ownModels, prompt, prompts, modules, staleNames, ownModules, wordsDiffer, ...rest }) => rest;
  assert.deepEqual(strip(fromConfig), strip(named), "the config's models are what naming them would give");
  assert.deepEqual([named.ownModels, fromConfig.ownModels], [true, false]);
  assert.equal(fromConfig.model, texModel("fd"));
  assert.equal(fromConfig.advisor, texStep("advisor").on ? texModel("advisor") : null);
  // The fallback model is the Front door's own setting (Dev2, 2026-11-16), the Fallback step kept turned off.
  assert.equal(texStep("fallback").on, false);
  assert.equal(typeof texStep("fd").fallback, "string", "the Front door names a fallback model");
  assert.equal(fromConfig.fallback, TEX_CONFIG.models[texStep("fd").fallback]);
  assert.equal(fromConfig.efforts[texModel("fd")], texStep("fd").effort);
  assert.equal(fromConfig.planBigAsks, texStep("planner").on);
  assert.equal(fromConfig.replyJudge !== null, texStep(texPick(["answerCheck", "reviewer"])).on);

  // A reviewer line left in a note with no models is the config's to answer, and is named.
  const stale = await parseSetup(bare.replace(/^---\n/, "---\nreply_judge: off\n"));
  assert.equal(stale.replyJudge !== null, texStep(texPick(["answerCheck", "reviewer"])).on);
  assert.deepEqual([stale.ownModels, stale.ignored], [false, ["reply_judge"]]);
  // A bench variant keeps the models it was written to compare, and says so.
  const variant = await parseSetup(bare.replace(/^---\n/, "---\nmodels:\n  main: anthropic/claude-sonnet-5-5\n"));
  assert.deepEqual([variant.model, variant.ownModels], ["anthropic/claude-sonnet-5-5", true]);
});

test("the advisor's four roles share one model and effort in code, so the config gives them one", () => {
  for (const id of ["jobcheck", "mailadv", "planner", "jobadv"]) {
    assert.deepEqual([id, texModel(id), texStep(id).effort], [id, texModel("advisor"), texStep("advisor").effort]);
  }
  assert.deepEqual([texModel("job"), texStep("job").model], [texModel("fd"), texStep("fd").model], "a job runs on main");
});

test("the advisor runs on Sonnet 5.5 at effort high (Finance, approved 2026-11-18; model-plan.md)", () => {
  assert.deepEqual([texModel("advisor"), texStep("advisor").effort], ["anthropic/claude-sonnet-5-5", "high"]);
});

test("a step the code cannot run is never on: the router needs a thinking model the config does not name yet", () => {
  assert.equal(texStep("router").on, false);
});

test("both send-backs reach the front door through the Answer check's one loop, on any draft (sendBack.js); the old steps' loops are gone", () => {
  // Dev2, 2026-11-16: the Answer checks (code) and the Reply reviewer (model) are one Answer check, its loop on every draft.
  const loops = TEX_CONFIG.edges.filter((e) => e.mode === "loop" && e.to === "fd").map((e) => [e.from, e.when.join()]);
  assert.deepEqual(loops, [["answerCheck", "*"]]);
  assert.ok(TEX_CONFIG.edges.some((e) => e.from === "fd" && e.to === "answerCheck" && e.mode === "wait"), "every draft reaches the Answer check");
  // An ask from another chat goes back to it instead of being texted (Dev2, 2026-11-17, cross-chat asks).
  assert.deepEqual(TEX_CONFIG.edges.filter((e) => e.from === "answerCheck" && e.mode !== "loop").map((e) => [e.to, e.when.join()]), [["send", "*"], ["chatAnswer", "ask"]]);
  for (const id of ["reviewer", "checks"]) assert.equal(texStep(id).on, false, `${id} is off`);
});

test("the generated words are the Markdown files' (scripts/tex-prompt-module.mjs)", () => {
  assert.ok(promptModuleIsCurrent(), "run node scripts/tex-prompt-module.mjs");
});

test("each step's prompt modules are the p- entries of its context, in order, and each has words", () => {
  // A `train:<node>` entry stands where it is as `train-<node>` once that node has Training labels, and a
  // `train:<node>:all:<chars>` one as `train-<node>-all-<chars>` (texTraining.cjs).
  const of = (id) =>
    texStep(id)
      .ctx.map((c) => (c.startsWith("p-") ? c.slice(2) : trainName(c) && TEX_PROMPT_WORDS[trainName(c)] ? trainName(c) : null))
      .filter(Boolean);
  // Each specialist door reads the p- entries of its own node's context (fdQuick, fdRead, fdAct), its door words among them.
  const door = (route) => of({ quick: "fdQuick", read: "fdRead", act: "fdAct" }[route]);
  assert.deepEqual(texModules(), { texts: of("fd"), group: of("fd"), job: of("job"), "door-quick": door("quick"), "door-read": door("read"), "door-act": door("act") });
  for (const name of new Set([...of("fd"), ...of("job"), ...door("quick"), ...door("read"), ...door("act")])) assert.equal(typeof TEX_PROMPT_WORDS[name], "string", name);
});

test("a note naming neither models nor modules, as production's does, is given the config's modules and the repository's words", async () => {
  const bare = readFileSync(FINGERPRINT_SETUP, "utf8");
  assert.doesNotMatch(bare, /^modules:/m, "the fingerprint copy names no modules, as production's note names none");
  const setup = await parseSetup(bare);
  const { texts, job } = texModules();
  assert.deepEqual(setup.modules, texModules());
  assert.equal(setup.prompts.texts, texts.map((n) => TEX_PROMPT_WORDS[n]).join("\n\n"));
  assert.equal(setup.prompts.group, setup.prompts.texts);
  assert.equal(setup.prompts.job, job.map((n) => TEX_PROMPT_WORDS[n]).join("\n\n"));
  assert.deepEqual([setup.ownModules, setup.wordsDiffer], [false, []]);
});

test("a note that names its own modules keeps them, and says which of Tex's modules it words differently", async () => {
  const lists = texModules();
  const raw = readFileSync(FINGERPRINT_SETUP, "utf8").replace(/^---\n/, `---\nmodules:\n  texts: [${lists.texts.join(", ")}]\n  job: [${lists.job.join(", ")}]\n`);
  const words = (path) => {
    const name = path.slice(path.lastIndexOf("/") + 1, -3);
    const text = TEX_PROMPT_WORDS[name];
    return Promise.resolve(path === modulePath("rules") ? `---\nmodule: rules\n---\n\n${text} One more line.\n` : `---\nmodule: ${name}\n---\n\n${text}\n`);
  };
  const setup = await parseSetup(await assembleSetup(raw, words, frontOf));
  assert.deepEqual([setup.ownModules, setup.wordsDiffer], [true, ["rules"]]);
  assert.match(setup.prompts.texts, /One more line\./);
});

test("only a texting setup is read with Tex's config: another job's note with no models is refused, as before", async () => {
  assert.equal(await parseSetup("---\njob: dream\n---\n\nDream words.\n"), null);
  const named = await parseSetup("---\njob: dream\nmodels:\n  main: anthropic/claude-haiku-5-5\n---\n\nDream words.\n");
  assert.equal(named.prompt, "Dream words.");
});
